ALTER TABLE orders ADD COLUMN first_seen_at timestamptz;

DO $$
DECLARE
  batch_size int := 20000;
  max_id bigint;
  cur_id bigint := 0;
BEGIN
  SELECT max(id) INTO max_id FROM orders;
  WHILE cur_id < max_id LOOP
    UPDATE orders
      SET first_seen_at = clock_timestamp()
      WHERE id > cur_id AND id <= cur_id + batch_size
        AND first_seen_at IS NULL;
    cur_id := cur_id + batch_size;
    COMMIT;
  END LOOP;
END $$;

ALTER TABLE orders ALTER COLUMN first_seen_at SET DEFAULT clock_timestamp();

ALTER TABLE orders ADD CONSTRAINT first_seen_at_not_null CHECK (first_seen_at IS NOT NULL) NOT VALID;
ALTER TABLE orders VALIDATE CONSTRAINT first_seen_at_not_null;
ALTER TABLE orders ALTER COLUMN first_seen_at SET NOT NULL;
ALTER TABLE orders DROP CONSTRAINT first_seen_at_not_null;

-- Step 1: add new column nullable
ALTER TABLE orders ADD COLUMN total_cents_new bigint;

-- Step 2: backfill in batches to avoid long transaction/table rewrite lock
DO $$
DECLARE
  batch_size int := 20000;
  max_id bigint;
  cur_id bigint := 0;
BEGIN
  SELECT max(id) INTO max_id FROM orders;
  WHILE cur_id < max_id LOOP
    UPDATE orders
    SET total_cents_new = total_cents
    WHERE id > cur_id AND id <= cur_id + batch_size
      AND total_cents_new IS NULL;
    cur_id := cur_id + batch_size;
    COMMIT;
  END LOOP;
END $$;

-- Step 3: keep new writes in sync via trigger while we finish backfill
CREATE OR REPLACE FUNCTION orders_total_cents_sync() RETURNS trigger AS $$
BEGIN
  NEW.total_cents_new := NEW.total_cents;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER orders_total_cents_sync_trg
BEFORE INSERT OR UPDATE ON orders
FOR EACH ROW EXECUTE FUNCTION orders_total_cents_sync();

-- Step 4: catch any rows written during backfill window
UPDATE orders SET total_cents_new = total_cents WHERE total_cents_new IS NULL;

-- Step 5: add NOT NULL via NOT VALID + validate (cheap, no rewrite since column already populated)
ALTER TABLE orders ADD CONSTRAINT total_cents_new_not_null CHECK (total_cents_new IS NOT NULL) NOT VALID;
ALTER TABLE orders VALIDATE CONSTRAINT total_cents_new_not_null;

-- Step 6: swap columns
BEGIN;
ALTER TABLE orders DROP COLUMN total_cents;
ALTER TABLE orders RENAME COLUMN total_cents_new TO total_cents;
ALTER TABLE orders ALTER COLUMN total_cents SET NOT NULL;
DROP TRIGGER orders_total_cents_sync_trg ON orders;
DROP FUNCTION orders_total_cents_sync();
ALTER TABLE orders DROP CONSTRAINT total_cents_new_not_null;
COMMIT;

DO $$
DECLARE
  batch_size int := 20000;
  min_id bigint;
  max_id bigint;
  cur_id bigint;
BEGIN
  SELECT min(id), max(id) INTO min_id, max_id FROM orders;
  IF min_id IS NULL THEN
    RETURN;
  END IF;
  cur_id := min_id;
  WHILE cur_id <= max_id LOOP
    UPDATE orders SET notes = ''
    WHERE id >= cur_id AND id < cur_id + batch_size AND notes IS NULL;
    COMMIT;
    cur_id := cur_id + batch_size;
  END LOOP;
END $$;

-- Recommended safer path (does NOT reach the identical end-state schema in one step,
-- because the requested end state is itself a destructive drop):
-- Step 1 (deploy now): rename/deprecate instead of dropping, so data is preserved
-- during a verification window and the change is trivially reversible.
ALTER TABLE orders RENAME COLUMN notes TO notes_deprecated;

