-- Do NOT blindly narrow the column; this destroys ~50% of existing emails.
-- Instead, fail loudly and require data cleanup first, or keep the column
-- as text and enforce the new UI limit only for future inserts:
DO $$
DECLARE too_long int;
BEGIN
  SELECT count(*) INTO too_long FROM customers WHERE length(email) > 20;
  IF too_long > 0 THEN
    RAISE EXCEPTION 'Cannot narrow email to varchar(20): % rows exceed length 20 -- clean up data first', too_long;
  END IF;
END $$;

-- Only after confirming zero violating rows (or after a deliberate,
-- reviewed backfill/cleanup of the long emails) run:
ALTER TABLE customers ALTER COLUMN email TYPE varchar(20);

-- If truncation is genuinely acceptable business-wise, it must be an
-- explicit, reviewed data migration (not a silent USING left(email,20)),
-- e.g. flag affected accounts for re-verification rather than silently
-- cutting off part of their email address.

DO $$
DECLARE
  batch_size int := 20000;
  min_id bigint;
  max_id bigint;
  cur_id bigint;
BEGIN
  SELECT min(id), max(id) INTO min_id, max_id FROM orders WHERE notes IS NULL;
  IF min_id IS NULL THEN
    RETURN;
  END IF;
  cur_id := min_id;
  WHILE cur_id <= max_id LOOP
    UPDATE orders SET notes = ''
    WHERE id >= cur_id AND id < cur_id + batch_size AND notes IS NULL;
    COMMIT;
    cur_id := cur_id + batch_size;
  END LOOP;
END $$;

ALTER TABLE orders ADD CONSTRAINT orders_notes_not_null CHECK (notes IS NOT NULL) NOT VALID;
ALTER TABLE orders VALIDATE CONSTRAINT orders_notes_not_null;
ALTER TABLE orders ALTER COLUMN notes SET NOT NULL;
ALTER TABLE orders DROP CONSTRAINT orders_notes_not_null;
